private static string SerializeError(LacerteSDKError err, string cid)
{
    var remediation = err.Remediation;
    if (!string.IsNullOrEmpty(remediation))
    {
        if (remediation.Contains("{cid}"))
            remediation = remediation.Replace("{cid}", cid);
        if (remediation.Contains("{logPath}"))
            remediation = remediation.Replace("{logPath}", WireLog.GetEffectiveLogPath() ?? "<set LACERTE_DEBUG_WIRE=1 first>");
    }
    var envelope = new Dictionary<string, object?>
    {
        ["success"] = false,
        ["statusCode"] = err.StatusCode,
        ["statusName"] = err.StatusName,
        ["severity"] = err.Severity.ToString().ToLowerInvariant(),
        ["userMessage"] = err.UserMessage,
        ["remediation"] = remediation,
        ["context"] = err.Context,
        ["cid"] = cid,
    };
    return WireLog.Redact(JsonSerializer.Serialize(envelope, JsonOptions), RedactionScope.Wire);
}
